(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='momcozy-framework-fw01';
const names={identity:'身份选择',stage:'所处阶段',basic:'基本信息',birth:'本次分娩',focus:'当前关注',recommend:'服务推荐',chat:'主对话',breast:'亲喂',formula:'配方奶',bottle:'瓶喂母乳',diaper:'换尿布',pump:'吸奶'};
const order=['identity','stage','basic','birth','focus','recommend','chat'];
const types=['breast','formula','bottle','diaper','pump'];
const initial=()=>({inputs:{},records:[],messages:[],chatDraft:'',attachment:false,tasks:{cry:{state:'ready',visible:false},poop:{state:'ready',visible:false,count:0}},editing:{},sound:false});
let epoch=0;let data=initial(),storage=true,route='',taskTimers={},recordClock=null,seconds=0,saving=false,sending=false,lastFocus=null;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.inputs&&Array.isArray(parsed.records)&&parsed.tasks){data={...initial(),...parsed};}}}catch{storage=false;}
if(!data.editing||typeof data.editing!=='object')data.editing={};
for(const t of Object.values(data.tasks)){if(t.state==='processing')t.state='error';if(t.state==='capture')t.state='ready';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localNow=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(data));storage=true;}catch{storage=false;}$('#storage-note').textContent=storage?'演示数据保留于当前浏览器，重置仅清除此原型数据。':'浏览器存储不可用：当前仅在内存中保留，刷新会丢失。';};
function capture(){for(const el of $$('[name]'))data.inputs[el.name]=el.type==='checkbox'?el.checked:el.value;data.chatDraft=$('#chat-input').value;persist();}
function restore(){for(const el of $$('[name]')){const v=data.inputs[el.name];if(v!==undefined){if(el.type==='checkbox')el.checked=v;else el.value=v;}}$('#chat-input').value=data.chatDraft;render();}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2600);}
function fail(s,el){$('#global-error').textContent=s;$('#global-error').hidden=false;if(el)el.focus();return false;}
function showDialog(title,body){$('#overlay').classList.toggle('sheet',title==='记录一次日常');lastFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#overlay').showModal();}
function closeDialog(){$('#overlay').close();if(lastFocus?.isConnected)lastFocus.focus();}
function go(to){capture();if(location.hash==='#/'+to){showRoute();return;}location.hash='#/'+to;}
function showRoute(){capture();route=location.hash.slice(2);if(!names[route]){route='chat';history.replaceState(null,'','#/chat');}$$('[data-page-id]').forEach(e=>e.hidden=e.dataset.route!=='#/'+route);$('#global-error').hidden=true;$('#page-title').textContent=names[route];$('#page-description').textContent=types.includes(route)?'独立记录表单。共用时间、备注、保存反馈；类型专属字段保持不同含义。':route==='chat'?'主会话承载消息和分析任务；记录进入独立表单，保存摘要返回当前会话。':'身份＋5步引导。只还原已提供的产后路径，返回保留输入。';if(types.includes(route)){const el=$(`[name="${route}-time"]`);if(!el.value)el.value=localNow();}render();$(`[data-route="#/${route}"] h1`)?.focus({preventScroll:true});window.scrollTo(0,0);}
function render(){
 const born=data.inputs['ONB-date'];const count=data.inputs['ONB-count'];const d=born?Math.floor((Date.now()-new Date(born+'T00:00:00'))/86400000):null;
 $('#stage-context').textContent=d!==null&&d>=0?`宝宝出生 ${d} 天${count&&count!=='1'?' · '+count+'个宝宝（本版未分档）':''}`:'产后照护 · 示例背景';
 $$('.record-baby').forEach(e=>e.textContent=count&&count!=='1'?'本次分娩背景（未分宝宝）':'本次背景');
 $('[data-control-id="C03"]').textContent=data.sound?'声音开启（模拟）':'声音关闭';
 $('#messages').innerHTML=data.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':'Momcozy AI · 演示'}</small>${esc(m.text)}</div>`).join('');
 $('#saved-records').innerHTML=data.records.map(r=>`<article class="saved"><div class="eyebrow">${storage?'已保存至本浏览器':'仅保留于当前页面'}</div><h2>${esc(names[r.type])} · ${r.type==='pump'?'妈妈':'宝宝'}</h2><p>${esc(summary(r))}</p><button data-action="edit:${r.id}">查看 / 修改记录</button></article>`).join('');
 $('#attachment').hidden=!data.attachment;$('#attachment').innerHTML='已添加 1 张模拟图片　<button data-action="remove-attachment">移除</button>';
 for(const kind of ['cry','poop']){const task=data.tasks[kind],card=$('#'+kind+'-card');card.hidden=!task.visible;card.querySelectorAll('[data-task-state]').forEach(el=>el.hidden=el.dataset.taskState!==task.state);card.querySelector('.task-footer').hidden=['cancelled','result','unknown'].includes(task.state);$('#'+kind+'-preview').textContent=kind==='cry'?`模拟录音 · ${task.seconds||0} 秒（未采集真实音频）`:`已选择 ${task.count||0} / 3 张模拟图片`;}
}
function summary(r){const v=r.values,k=r.type;let s=(v[k+'-time']||'').replace('T',' ')+' · '+(r.timezone||'设备本地时间')+'\n';if(k==='breast')s+=v[k+'-side']+' · '+v[k+'-duration']+' 分钟';else if(k==='diaper')s+=v[k+'-diaper']+' · 红屁屁：'+v[k+'-rash'];else s+=v[k+'-amount']+' ml'+(v[k+'-end']?' · 结束 '+v[k+'-end'].replace('T',' '):'');if(v[k+'-note'])s+='\n备注：'+v[k+'-note'];return s;}
function next(){capture();let required={identity:['ONB-role'],stage:['ONB-stage'],basic:['ONB-age','ONB-parity'],birth:['ONB-date','ONB-week','ONB-count']}[route]||[];for(const key of required){const el=$(`[name="${key}"]`);if(!el.value||!el.checkValidity())return fail('请补充或检查：'+el.closest('label').childNodes[0].textContent,el);}if(route==='stage'&&data.inputs['ONB-stage']!=='产后'){$('#stage-note').hidden=false;return;}if(route==='birth'&&data.inputs['ONB-date']>localNow().slice(0,10))return fail('分娩日期不能晚于今天。',$('[name="ONB-date"]'));go(order[order.indexOf(route)+1]||'chat');}
function recordMenu(){showDialog('记录一次日常',`<p class="muted">选择类型，进入对应表单。</p><div class="dialog-list">${types.map((x,i)=>`<button data-action="new:${x}">${names[x]}<small>${['侧别与时长','奶量与时间','奶量与时间','尿布状态与观察','妈妈的吸奶量'][i]}</small></button>`).join('')}</div>`);}
function save(k){if(saving)return;capture();const keys=[k+'-time',...(k==='breast'?[k+'-side',k+'-duration']:k==='diaper'?[k+'-diaper',k+'-rash']:[k+'-amount'])];const err=$('#'+k+'-error');err.hidden=true;for(const key of keys){const el=$(`[name="${key}"]`);if(!el.value||!el.checkValidity()){err.textContent='请检查必填字段，数值需大于 0。';err.hidden=false;el.focus();return;}}const start=data.inputs[k+'-time'],end=data.inputs[k+'-end'];if(start>localNow()||end&&(end<start||end>localNow())){err.textContent='请检查时间：不能晚于当前时间，结束不能早于开始。';err.hidden=false;return;}const values=Object.fromEntries(Object.entries(data.inputs).filter(([key])=>key.startsWith(k+'-'))), editId=data.editing[k], operationEpoch=epoch;saving=true;$('#'+k+'-saving').hidden=false;$(`[data-control-id="${k}-save"]`).disabled=true;setTimeout(()=>{if(epoch!==operationEpoch)return;saving=false;$('#'+k+'-saving').hidden=true;$(`[data-control-id="${k}-save"]`).disabled=false;if($('#scenario-save').value==='fail'){err.textContent='保存失败，填写内容已保留。请切换正常场景后重试。';err.hidden=false;return;}const id=editId||'rec-'+Date.now();const r={id,type:k,values,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,createdAt:new Date().toISOString()};const idx=data.records.findIndex(x=>x.id===id);if(idx<0)data.records.push(r);else data.records[idx]=r;delete data.editing[k];for(const el of $$(`[data-page-id="PAGE-${k}"] [name]`)){el.value='';delete data.inputs[el.name];}capture();go('chat');toast(storage?'记录已保存至本浏览器':'仅保留于当前页面，刷新会丢失');},450);}
function edit(id,force=false){const r=data.records.find(x=>x.id===id);if(!r)return;capture();const dirty=$$(`[data-page-id="PAGE-${r.type}"] [name]`).some(el=>!el.name.endsWith('-time')&&el.value);if(!force&&dirty){if(data.editing[r.type]===id){go(r.type);return;}showDialog('已有未保存填写','<p>同类型有未保存内容，请选择继续或放弃后打开另一条记录。</p><div class="dialog-list"><button data-action="resume-type:'+r.type+'">继续已有填写</button><button data-action="replace-edit:'+id+'">放弃已有填写并打开记录</button></div>');return;}data.editing[r.type]=id;for(const el of $$(`[data-page-id="PAGE-${r.type}"] [name]`)){el.value=r.values[el.name]||'';}capture();go(r.type);}
function taskAction(kind,action){const t=data.tasks[kind];
 if(action==='open'){t.visible=true;if(['cancelled','result','unknown'].includes(t.state)){data.messages.push({role:'assistant',text:(kind==='cry'?'听哭闹':'看便便')+' · 上次任务'+(t.state==='cancelled'?'已取消':t.state==='unknown'?'无法判断':'已完成（结构示例）')+'。'});t.state='ready';t.count=0;t.seconds=0;}go('chat');render();$('#'+kind+'-card').scrollIntoView({block:'center'});$('#'+kind+'-card h2').focus({preventScroll:true});return;}
 if(action==='cancel'){clearTimeout(taskTimers[kind]);if(kind==='cry')clearInterval(recordClock);t.state='cancelled';t.count=0;t.seconds=0;}
 if(action==='restart'){t.state='ready';t.count=0;t.seconds=0;}
 if(action==='start'){if(data.tasks.cry.state==='capture')return;if($('#scenario-permission').value==='deny'){t.state='permission';}else{t.state='capture';seconds=0;$('#recording-time').textContent='00:00';clearInterval(recordClock);recordClock=setInterval(()=>{seconds++;$('#recording-time').textContent='00:'+String(seconds).padStart(2,'0');},1000);}}
 if(action==='stop'){clearInterval(recordClock);t.seconds=Math.max(1,seconds);t.state='preview';}
 if(action==='add'){if($('#scenario-permission').value==='deny'){t.state='permission';}else if((t.count||0)>=3){toast('最多添加 3 张图片');}else{t.count=(t.count||0)+1;t.state='preview';}}
 if(action==='remove'){t.count=Math.max(0,(t.count||0)-1);t.state=t.count?'preview':'ready';}
 if(action==='submit'){if(t.state==='processing')return;if(kind==='poop'&&!t.count||kind==='cry'&&!t.seconds){t.state='ready';}else{t.state='processing';const outcome=$('#scenario-analysis').value;clearTimeout(taskTimers[kind]);taskTimers[kind]=setTimeout(()=>{t.state=outcome;persist();render();},1000);}}
 if(action==='ask'){$('#chat-input').value='关于刚才的'+(kind==='cry'?'哭声':'便便')+'结果，我想补充：';$('#chat-input').focus();toast('已带入任务名称，请补充情况');}
 persist();render();
}
function send(){if(sending)return;const input=$('#chat-input'),text=input.value.trim();if(!text&&!data.attachment){toast('请先输入内容或添加图片');return;}capture();const sentAttachment=data.attachment,operationEpoch=epoch;sending=true;$('#generating').hidden=false;$('[data-control-id="CHAT-send"]').disabled=true;$('#chat-error').hidden=true;setTimeout(()=>{if(epoch!==operationEpoch)return;sending=false;$('#generating').hidden=true;$('[data-control-id="CHAT-send"]').disabled=false;if($('#scenario-save').value==='fail'){$('#chat-error').hidden=false;return;}data.messages.push({role:'user',text:(text||'请看看这张图片')+(sentAttachment?'\n[模拟图片]':'')},{role:'assistant',text:'已收到。这里演示对话回复的位置与层级。你可以继续补充情况，或通过下方入口记录日常。此回复不包含真实 AI 分析。'});if(input.value.trim()===text){input.value='';data.chatDraft='';}else data.chatDraft=input.value;data.attachment=false;persist();render();},600);}
const scopeHTML=`<p><strong>本版：独立产品容器，范围限定为已录入功能。</strong></p><h3>原始来源</h3><p>「重构需求拆解与原型交互」聊天 2026-10-19 的 17 张截图与拆解，已保存在 sources。保留 C01–C15、C09.1–C09.5 编号。</p><h3>必要完善（候选规则）</h3><p>返回保留草稿；五类记录本地保存并回到会话；记录可修改；亲喂时长采用手动补记；素材先确认再分析；失败重试与取消。</p><h3>待定业务</h3><p>奶量含义、亲喂计时、年龄和孕周范围、正式默认值、时间与单位规则、语音与声音入口具体行为。数值和校验仅用于演示。</p><h3>范围外 / 未提供</h3><p>备孕与孕期分支、侧菜单完整内容、多宝宝分档、账号、家庭共享、设备绑定、商城、通知、后台同步、真实 AI / 麦克风 / 相机。</p><p>情绪板仅作方向参考。本版框架与设计规范尚未冻结。</p>`;
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;if(sending&&['attachment','remove-attachment','voice','voice-text'].includes(button.dataset.action)){toast('正在发送，完成后可添加下一条素材');return;}if(saving&&button.dataset.action!=='reset-confirm'){toast('正在保存，请稍候');return;}const [action,arg,more]=button.dataset.action.split(':');$('#global-error').hidden=true;
if(action==='go'||action==='review')go(arg);else if(action==='next')next();else if(action==='menu')showDialog('菜单',`<p class="notice">原始材料仅显示菜单入口，菜单内容尚未提供。</p><div class="dialog-list"><button data-action="menu-profile">回看已录入背景 <small>为已有引导提供必要返回入口</small></button><button data-action="close-dialog">返回当前对话</button></div>`);else if(action==='menu-profile'){closeDialog();go('identity');}else if(action==='sound'){data.sound=!data.sound;persist();render();toast('声音状态为模拟，本版不自动播放');}else if(action==='record-menu')recordMenu();else if(action==='new'){closeDialog();go(arg);}else if(action==='close-dialog')closeDialog();else if(action==='save')save(arg);else if(action==='exit'){capture();if(saving){toast('正在保存，请稍候');return;}const hasInput=$$(`[data-page-id="PAGE-${arg}"] [name]`).some(el=>!el.name.endsWith('-time')&&el.value);if(hasInput)showDialog('保留这次填写？','<p>保留后可从同一记录类型继续。</p><div class="dialog-list"><button data-action="keep-draft">保留草稿并返回</button><button data-action="discard:'+arg+'">放弃填写并返回</button><button data-action="close-dialog">继续填写</button></div>');else go('chat');}else if(action==='keep-draft'){closeDialog();go('chat');}else if(action==='discard'){for(const el of $$(`[data-page-id="PAGE-${arg}"] [name]`))el.value='';delete data.editing[arg];capture();closeDialog();go('chat');}else if(action==='edit')edit(arg);else if(action==='resume-type'){closeDialog();go(arg);}else if(action==='replace-edit'){closeDialog();edit(arg,true);}else if(action==='amount'){const el=$(`[name="${arg}-amount"]`);el.value=Math.max(0,Number(el.value||0)+Number(more));capture();}else if(action==='cry'||action==='poop')taskAction(action,arg);else if(action==='send')send();else if(action==='attachment'){data.attachment=true;persist();render();toast('已添加模拟图片，不调用相机');}else if(action==='remove-attachment'){data.attachment=false;persist();render();}else if(action==='voice')showDialog('语音输入 · 模拟','<p>原入口具体语音形态尚未定义。本版仅演示“转成文字 → 用户确认发送”。</p><button data-action="voice-text">使用示例转写</button>');else if(action==='voice-text'){$('#chat-input').value='我想了解如何记录这次喂养。';capture();closeDialog();}else if(action==='more')showDialog('更多','<p>原始材料未给出扩展项清单，本轮保留入口，不新增功能。</p>');else if(action==='scope')showDialog('范围与来源',scopeHTML);else if(action==='reset')showDialog('重置演示','<p>只清除此框架的虚构输入、会话、任务与记录。</p><button data-action="reset-confirm" class="primary">确认重置</button>');else if(action==='reset-confirm'){epoch++;saving=false;sending=false;$('#generating').hidden=true;$('[data-control-id="CHAT-send"]').disabled=false;clearInterval(recordClock);Object.values(taskTimers).forEach(clearTimeout);data=initial();$$('[name]').forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value='';});$('#chat-input').value='';persist();closeDialog();go('chat');}
});
document.addEventListener('input',e=>{if(e.target.matches('[name],#chat-input'))capture();});document.addEventListener('change',e=>{if(e.target.name==='ONB-stage')$('#stage-note').hidden=e.target.value==='产后';});
$('#chat-input').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();send();}});
$('#overlay').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
window.addEventListener('hashchange',showRoute);window.addEventListener('pagehide',capture);
restore();persist();showRoute();
})();
